export function encodeArtifactProjectionEntry(v: ArtifactProjectionEntry): string {
  const parts: string[] = [];
  parts.push(`${jstr("name")}:${jstr(v.name)}`);
  parts.push(`${jstr("origin")}:${jstr(v.origin)}`);
  parts.push(`${jstr("content")}:${jstr(v.content)}`);
  if (v.labels !== undefined && Object.keys(v.labels).length > 0) parts.push(`${jstr("labels")}:${`{${Object.keys(v.labels!).sort().map((k0) => `${jstr(k0)}:${jstr(v.labels![k0])}`).join(",")}}`}`);
  if (v.annotations !== undefined && Object.keys(v.annotations).length > 0) parts.push(`${jstr("annotations")}:${`{${Object.keys(v.annotations!).sort().map((k0) => `${jstr(k0)}:${jstr(v.annotations![k0])}`).join(",")}}`}`);
  return `{${parts.join(",")}}`;
}

export function decodeArtifactProjectionEntry(data: string): ArtifactProjectionEntry {
  return JSON.parse(data) as ArtifactProjectionEntry;
}

export function encodeAssembleBoundaryInput(v: AssembleBoundaryInput): string {
  const parts: string[] = [];
  if (v.boundary !== undefined && v.boundary !== null) parts.push(`${jstr("boundary")}:${encodeOpaque(v.boundary)}`);
  parts.push(`${jstr("rendered_nodes")}:${`[${v.rendered_nodes!.map((e0) => encodeRenderedNode(e0)).join(",")}]`}`);
  parts.push(`${jstr("context")}:${encodeOpaque(v.context)}`);
  parts.push(`${jstr("boundary_path")}:${jstr(v.boundary_path)}`);
  if (v.edges !== undefined && v.edges.length > 0) parts.push(`${jstr("edges")}:${`[${v.edges!.map((e0) => encodeRenderEdge(e0)).join(",")}]`}`);
  if (v.sub_charts !== undefined && v.sub_charts.length > 0) parts.push(`${jstr("sub_charts")}:${`[${v.sub_charts!.map((e0) => encodeSubChart(e0)).join(",")}]`}`);
  if (v.chart_name !== undefined && v.chart_name !== "") parts.push(`${jstr("chart_name")}:${jstr(v.chart_name)}`);
  if (v.aggregate_name !== undefined && v.aggregate_name !== "") parts.push(`${jstr("aggregate_name")}:${jstr(v.aggregate_name)}`);
  return `{${parts.join(",")}}`;
}

export function decodeAssembleBoundaryInput(data: string): AssembleBoundaryInput {
  return JSON.parse(data) as AssembleBoundaryInput;
}

export function encodeRenderedNode(v: RenderedNode): string {
  const parts: string[] = [];
  parts.push(`${jstr("id")}:${jstr(v.id)}`);
  parts.push(`${jstr("type")}:${jstr(v.type)}`);
  parts.push(`${jstr("rendered")}:${encodeRenderNodeOutput(v.rendered)}`);
  if (v.annotations !== undefined && Object.keys(v.annotations).length > 0) parts.push(`${jstr("annotations")}:${`{${Object.keys(v.annotations!).sort().map((k0) => `${jstr(k0)}:${jstr(v.annotations![k0])}`).join(",")}}`}`);
  return `{${parts.join(",")}}`;
}

export function decodeRenderedNode(data: string): RenderedNode {
  return JSON.parse(data) as RenderedNode;
}

